/**
 * exemples-sectoriels-ext.ts — Extension des packs d'exemples sectoriels (ateliers 1 à 5).
 *
 * Contenu ajouté le 2026-10-03 : santé (portail d'accès aux données de santé, entrepôt de
 * données de santé, délégataire de gestion, plans de traitement des sous-secteurs existants),
 * assurance santé / mutuelle (AMC) et nouvelle catégorie « Technique / Interconnexion de SI ».
 *
 * Différence avec `exemples-sectoriels.ts` : les textes sont écrits dans les 5 langues DANS la
 * donnée (tuples fr/en/de/es/it), pas dans des dictionnaires indexés par position ; ajouter ou
 * retirer un élément ne décale donc aucune traduction. Les champs d'énumération (type, catégorie,
 * critère, catégorie EBIOS) ne sont jamais traduits.
 *
 * `profs` : sous-professions qui voient l'élément (cf. `professionFromSousSecteur`) ; absent =
 * élément commun à toute la famille. Les références citent un texte et sa version, sans en
 * reproduire le contenu. Contenu « à relire par un expert du secteur » : suggestions à qualifier.
 *
 * Module pur → testé (exemples-sante-interco.test.ts).
 */
import type { Locale } from '@/lib/i18n'
import { PROTECTION_SOCIALE_ITEMS } from '@/lib/exemples-protection-sociale'

export type Tr = readonly [fr: string, en: string, de: string, es: string, it: string]
export type ExtCategory =
  | 'valeursMetier' | 'biensSupports' | 'evenementsRedoutes' | 'sourcesRisque' | 'scenariosStrategiques'
  | 'partiesPrenantes' | 'actionsElementaires' | 'mesuresEcosysteme' | 'mesures'

export interface ExtItem {
  famille: 'sante' | 'technique' | 'protection_sociale'
  category: ExtCategory
  profs?: readonly string[]
  /** Sous-professions pour lesquelles un élément commun à la famille serait incohérent (il ne leur est pas proposé). */
  notFor?: readonly string[]
  /** Champs : chaînes / nombres conservés tels quels ; `Tr` localisé ; `Tr[]` localisé élément par élément. */
  data: Record<string, unknown>
}

const L = (fr: string, en: string, de: string, es: string, it: string): Tr => [fr, en, de, es, it]
const isTr = (v: unknown): v is Tr => Array.isArray(v) && v.length === 5 && v.every(x => typeof x === 'string')
const LOCALE_INDEX: Record<Locale, number> = { fr: 0, en: 1, de: 2, es: 3, it: 4 }

/** Localise un élément d'extension (tuples → chaînes), sans le champ technique `profs`. */
export function localizeExt(item: ExtItem, locale: Locale): Record<string, unknown> {
  const i = LOCALE_INDEX[locale] ?? 0
  const out: Record<string, unknown> = {}
  for (const [k, v] of Object.entries(item.data)) {
    if (isTr(v)) out[k] = v[i]
    else if (Array.isArray(v) && v.length && v.every(isTr)) out[k] = (v as Tr[]).map(t => t[i])
    else out[k] = v
  }
  return out
}

/** Éléments d'extension visibles pour une famille, une catégorie et une sous-profession. */
export function extItemsFor(famille: string, category: string, prof: string | undefined): ExtItem[] {
  const visible = [...EXT_ITEMS, ...PROTECTION_SOCIALE_ITEMS].filter(x => x.famille === famille && x.category === category
    && (!x.profs || (prof !== undefined && x.profs.includes(prof)))
    && !(prof !== undefined && x.notFor?.includes(prof)))
  // Éléments propres à la sous-profession d'abord, puis éléments communs à la famille (tri stable).
  return [...visible.filter(x => x.profs), ...visible.filter(x => !x.profs)]
}

// ─── Constructeurs compacts ────────────────────────────────────────────────────
type Fam = ExtItem['famille']
type P = readonly string[] | null
const mk = (famille: Fam, category: ExtCategory, profs: P, data: Record<string, unknown>): ExtItem => ({ famille, category, ...(profs ? { profs } : {}), data })
const vm = (f: Fam, profs: P, nom: Tr, type: 'PROCESSUS' | 'INFORMATION', description: Tr, responsable: Tr, d: number, i: number, c: number, t: number) =>
  mk(f, 'valeursMetier', profs, { nom, type, description, responsable, disponibilite: d, integrite: i, confidentialite: c, tracabilite: t })
const bs = (f: Fam, profs: P, nom: Tr, type: string, description: Tr) => mk(f, 'biensSupports', profs, { nom, type, description })
const er = (f: Fam, profs: P, description: Tr, impacts: Tr[], graviteDefaut: number) => mk(f, 'evenementsRedoutes', profs, { description, impacts, graviteDefaut })
const sr = (f: Fam, profs: P, nom: Tr, categorie: string, description: Tr, motivation: Tr, ressources: Tr, pertinenceDefaut: number) =>
  mk(f, 'sourcesRisque', profs, { nom, categorie, description, motivation, ressources, pertinenceDefaut })
const ss = (f: Fam, profs: P, critere: 'C' | 'I' | 'D' | 'T', nom: Tr, description: Tr, vraisemblanceDefaut: number, graviteDefaut: number) =>
  mk(f, 'scenariosStrategiques', profs, { critere, nom, description, vraisemblanceDefaut, graviteDefaut })
const pp = (f: Fam, profs: P, nom: Tr, type: string, dependance: number, penetration: number, maturite: number, confiance: number) =>
  mk(f, 'partiesPrenantes', profs, { nom, type, dependance, penetration, maturite, confiance })
// `attack` : technique MITRE ATT&CK (Enterprise) correspondante — aide à détailler la chaîne d'attaque de l'atelier 4.
const ae = (f: Fam, profs: P, type: string, attack: string, nom: Tr, description: Tr) => mk(f, 'actionsElementaires', profs, { type, attack, nom, description })
const me = (f: Fam, profs: P, mesure: Tr, type: 'ORGANISATIONNELLE' | 'TECHNIQUE' | 'DETECTIVE' | 'PHYSIQUE', iso27005: string, description: Tr) =>
  mk(f, 'mesuresEcosysteme', profs, { mesure, type, iso27005, description })
type TypeMesure = 'PREVENTIVE' | 'DETECTIVE' | 'CORRECTIVE' | 'DISSUASIVE' | 'ORGANISATIONNELLE' | 'TECHNIQUE'
type CatEbios = 'GOUVERNANCE' | 'PROTECTION' | 'DEFENSE' | 'RESILIENCE'
const ms = (f: Fam, profs: P, nom: Tr, description: Tr, type: TypeMesure, categorieEbios: CatEbios, prioriteDefaut: 1 | 2 | 3 | 4, references?: string[]) =>
  mk(f, 'mesures', profs, { nom, description, type, categorieEbios, prioriteDefaut, ...(references ? { references } : {}) })

